word-project-charter:
using System.IO;
using OfficeIMO.Word;

namespace OfficeIMO.Examples.Showcase.Workflows;

/// <summary>Creates an editable project charter with scope, milestones, and named owners.</summary>
internal static class ProjectCharter {
    internal static void Create(string folder) {
        using WordDocument document = WordDocument.Create(Path.Combine(folder, "example.docx"));
        document.Settings.FontFamily = "Carlito";
        document.Settings.FontSize = 11;
        document.BuiltinDocumentProperties.Title = "Project charter";
        document.AddParagraph("Project charter").Style = WordParagraphStyles.Heading1;
        document.AddParagraph("NORTHWIND / CUSTOMER PORTAL / VERSION 1.0");
        document.AddParagraph("Give the delivery team one agreed reference for the outcome, scope, and acceptance decision.");

        document.AddParagraph("Outcome and boundaries").AddBookmark("Scope").Style = WordParagraphStyles.Heading2;
        WordList scope = document.AddList(WordListStyle.Bulleted);
        scope.AddItem("Provide a single place to submit and track service requests.");
        scope.AddItem("Include request history and a clear escalation path.");
        scope.AddItem("Keep billing and account administration outside this release.");

        document.AddParagraph("Delivery milestones").Style = WordParagraphStyles.Heading2;
        string[,] values = {
            { "Milestone", "Owner", "Acceptance evidence" },
            { "Discovery", "Product", "Reviewed service journey" },
            { "Pilot", "Engineering", "Ten completed pilot requests" },
            { "Launch", "Operations", "Support and recovery walkthrough" }
        };
        WordTable table = document.AddTable(4, 3, WordTableStyle.TableGrid);
        for (int row = 0; row < 4; row++) {
            for (int column = 0; column < 3; column++) {
                var paragraph = table.Rows[row].Cells[column].Paragraphs[0];
                paragraph.Text = values[row, column];
                paragraph.Bold = row == 0;
                if (row == 0) table.Rows[row].Cells[column].ShadingFillColorHex = "E8EEF8";
            }
        }
        document.AddParagraph("Success measure").Style = WordParagraphStyles.Heading2;
        document.AddParagraph("At least 90% of pilot requests reach the right team without manual reassignment.");
        foreach (WordParagraph paragraph in document.Paragraphs) {
            paragraph.FontFamily = "Carlito";
            paragraph.FontSize = 11;
            paragraph.LineSpacingAfterPoints = 7;
            if (paragraph.Style == WordParagraphStyles.Heading1) {
                paragraph.FontSize = 26;
                paragraph.Bold = true;
                paragraph.LineSpacingAfterPoints = 12;
            } else if (paragraph.Style == WordParagraphStyles.Heading2) {
                paragraph.FontSize = 15;
                paragraph.Bold = true;
                paragraph.LineSpacingBeforePoints = 12;
                paragraph.LineSpacingAfterPoints = 6;
            }
        }
        foreach (WordTable styledTable in document.Tables) {
            styledTable.SetWidthPercentage(100);
            styledTable.SetColumnWidthsPercentage(25, 22, 53);
            foreach (var row in styledTable.Rows) {
                foreach (var cell in row.Cells) {
                    cell.MarginTopCentimeters = 0.10;
                    cell.MarginBottomCentimeters = 0.10;
                    foreach (var paragraph in cell.Paragraphs) {
                        paragraph.FontFamily = "Carlito";
                        paragraph.FontSize = 11;
                        paragraph.LineSpacingAfterPoints = 3;
                    }
                }
            }
        }
        document.Save();
    }
}

excel-budget-scenarios:
using System.IO;
using OfficeIMO.Drawing;
using OfficeIMO.Excel;

namespace OfficeIMO.Examples.Showcase.Workflows;

/// <summary>Compares three budget scenarios using calculated cells and editable assumptions.</summary>
internal static class BudgetScenarios {
    internal static void Create(string folder) {
        using ExcelDocument document = ExcelDocument.Create(Path.Combine(folder, "example.xlsx"));
        ExcelSheet sheet = document.AddWorksheet("Scenarios");
        sheet.MergeRange("A1:F1");
        sheet.Cell(1, 1, "Budget scenarios / next quarter");
        sheet.CellFontSize(1, 1, 20);
        sheet.CellBold(1, 1, true);
        sheet.CellFontColor(1, 1, "17365D");
        sheet.MergeRange("A2:F2");
        sheet.Cell(2, 1, "Blue cells are assumptions. Green cells are calculated.");

        string[] headings = { "Scenario", "Units", "Unit price", "Revenue", "Fixed cost", "Contribution" };
        for (int column = 0; column < headings.Length; column++) {
            sheet.Cell(4, column + 1, headings[column]);
            sheet.CellBackground(4, column + 1, "17365D");
            sheet.CellFontColor(4, column + 1, "FFFFFF");
            sheet.CellBold(4, column + 1, true);
            sheet.SetColumnWidth(column + 1, column == 0 ? 25 : 20);
        }
        string[] labels = { "Conservative", "Expected", "Growth" };
        for (int index = 0; index < labels.Length; index++) {
            int row = index + 5;
            sheet.Cell(row, 1, labels[index]);
            sheet.Cell(row, 2, new[] { 800, 1100, 1500 }[index], numberFormat: "#,##0");
            sheet.Cell(row, 3, 85, numberFormat: "#,##0.00");
            sheet.CellFormula(row, 4, $"B{row}*C{row}");
            sheet.Cell(row, 5, 42000, numberFormat: "#,##0");
            sheet.CellFormula(row, 6, $"D{row}-E{row}");
            sheet.FormatCell(row, 4, "#,##0");
            sheet.FormatCell(row, 6, "#,##0");
            foreach (int column in new[] { 2, 3, 5 }) sheet.CellBackground(row, column, "EAF1FB");
            foreach (int column in new[] { 4, 6 }) sheet.CellBackground(row, column, "E7F6ED");
        }
        sheet.MergeRange("A10:F10");
        sheet.Cell(10, 1, "Change volume, price, or fixed cost to compare a different plan.");
        document.Calculate();
        sheet.Range("A1:F12").ExportImage(OfficeImageExportFormat.Png)
            .Save(Path.Combine(folder, "preview.png"), OfficeImageExportFileConflictPolicy.Replace);
        document.Save();
    }
}

powerpoint-project-roadmap:
using System.IO;
using OfficeIMO.PowerPoint;

namespace OfficeIMO.Examples.Showcase.Workflows;

/// <summary>Creates an editable roadmap deck with phase cards and a decision table.</summary>
internal static class ProjectRoadmap {
    internal static void Create(string folder) {
        using PowerPointPresentation deck = PowerPointPresentation.Create(Path.Combine(folder, "example.pptx"));
        PowerPointSlide roadmap = deck.AddSlide();
        Heading(roadmap, "From pilot to everyday service", "PROJECT ROADMAP / NEXT 90 DAYS");
        string[] phases = { "01 / Prepare", "02 / Prove", "03 / Expand" };
        string[] details = { "Agree the scope\nName the owners\nPrepare support", "Run the pilot\nExercise recovery\nCollect feedback", "Invite more teams\nReview the measures\nHand over ownership" };
        string[] colors = { "EAF1FB", "EEE8F7", "E7F6ED" };
        for (int index = 0; index < phases.Length; index++) {
            double x = 1.5 + index * 10.3;
            roadmap.AddRectangleCm(x, 5.5, 9.3, 9, phases[index]).Fill(colors[index]).Stroke("CBD5E1", 1);
            Text(roadmap, phases[index], x + 0.5, 6.1, 8.3, 1.4, 25);
            Text(roadmap, details[index], x + 0.5, 8.3, 8.3, 5, 21);
        }

        PowerPointSlide gates = deck.AddSlide();
        Heading(gates, "Advance on evidence", "DECISION CHECKPOINTS");
        PowerPointTable table = gates.AddTableCm(4, 3, 1.5, 5.3, 30, 10);
        string[,] values = {
            { "Checkpoint", "Evidence", "Decision owner" },
            { "Pilot ready", "Support and recovery walkthrough", "Operations" },
            { "Pilot complete", "Observed request outcomes", "Product" },
            { "Service accepted", "Named owner and runbook", "Service owner" }
        };
        for (int row = 0; row < 4; row++) {
            for (int column = 0; column < 3; column++) {
                var cell = table.GetCell(row, column);
                cell.Text = values[row, column];
                cell.FontSize = 19;
                cell.Bold = row == 0;
                cell.FillColor = row == 0 ? "17365D" : "F1F5F9";
                cell.Color = row == 0 ? "FFFFFF" : "17365D";
                cell.PaddingLeftPoints = 12;
                cell.VerticalAlignment = PowerPointTextVerticalAlignment.Center;
            }
        }
        deck.Save();

        void Heading(PowerPointSlide slide, string title, string subtitle) {
            Text(slide, title, 1.5, 1.3, 30, 1.8, 32);
            Text(slide, subtitle, 1.5, 3.4, 30, 1, 15);
        }
        void Text(PowerPointSlide slide, string value, double x, double y, double width, double height, int size) {
            var box = slide.AddTextBoxCm(value, x, y, width, height);
            box.FontSize = size;
            box.Color = "17365D";
        }
    }
}

pdf-workshop-pack:
using System.IO;
using OfficeIMO.Pdf;

namespace OfficeIMO.Examples.Showcase.Workflows;

/// <summary>Creates a two-page workshop pack with a shared header and numbered footer.</summary>
internal static class WorkshopPack {
    internal static void Create(string folder) {
        PdfColor accent = PdfColor.FromRgb(103, 58, 140);
        var options = new PdfOptions {
            DefaultFontSize = 11, ShowHeader = true, HeaderFormat = "NORTHWIND / SERVICE DESIGN",
            HeaderFontSize = 8, HeaderAlign = PdfAlign.Left,
            ShowPageNumbers = true, FooterFormat = "Workshop pack | {page} / {pages}",
            FooterFontSize = 8, FooterAlign = PdfAlign.Right
        };
        PdfDocument.Create(pdf => pdf.Content(content => content
            .H1("Service design workshop", PdfAlign.Left, accent)
            .Paragraph(p => p.Text("A half-day session to turn service feedback into a delivery plan."))
            .H2("What we will leave with", PdfAlign.Left, accent)
            .Bullets(new[] { "One agreed service journey", "Three prioritized improvements", "An owner and next step for each improvement" })
            .H2("Agenda", PdfAlign.Left, accent)
            .Table(new[] {
                new[] { "Time", "Session", "Output" },
                new[] { "09:00", "Current journey", "Shared map" },
                new[] { "09:45", "Friction and evidence", "Ranked pain points" },
                new[] { "10:45", "Options and trade-offs", "Three candidates" },
                new[] { "11:30", "Commitments", "Action list" }
            }, style: new PdfTableStyle {
                HeaderFill = accent, HeaderTextColor = PdfColor.White, HeaderRowCount = 1,
                CellPaddingX = 8, CellPaddingY = 8, RowStripeFill = PdfColor.FromRgb(247, 242, 251)
            })
            .PageBreak()
            .H1("Exercise sheet", PdfAlign.Left, accent)
            .H2("1. Describe one difficult moment", PdfAlign.Left, accent)
            .Paragraph(p => p.Text("Who is trying to do what, and where do they get stuck? Use an observed example."))
            .HR(0.5, PdfColor.FromRgb(203, 213, 225), 30, 30)
            .H2("2. Propose the smallest useful change", PdfAlign.Left, accent)
            .Paragraph(p => p.Text("Describe what the person will be able to do after the change."))
            .HR(0.5, PdfColor.FromRgb(203, 213, 225), 30, 30)
            .H2("3. Choose the first check", PdfAlign.Left, accent)
            .Paragraph(p => p.Text("What evidence would show that the change helped? Who will collect it?"))
            .HR(0.5, PdfColor.FromRgb(203, 213, 225), 30, 30)), options)
            .Meta(title: "Service design workshop pack", author: "OfficeIMO")
            .Save(Path.Combine(folder, "example.pdf"));
    }
}

markdown-incident-runbook:
using System.IO;
using OfficeIMO.Markdown;

namespace OfficeIMO.Examples.Showcase.Workflows;

/// <summary>Authors a portable incident runbook with structured steps, a decision table, and a warning.</summary>
internal static class IncidentRunbook {
    internal static void Create(string folder) {
        MarkdownDoc document = MarkdownDoc.Create()
            .H1("Service incident runbook")
            .P("Owner: Operations | Applies to: the Northwind request portal")
            .Callout("warning", "Before changing the service",
                "Confirm impact and name the incident owner. Record evidence before restarting components.")
            .H2("1. Establish the situation")
            .Ul(list => list.Item("Record the first observed failure and the affected user groups.")
                .Item("Check whether a deployment or configuration change preceded the failure.")
                .Item("Open an incident record and agree the next update time."))
            .H2("2. Choose the next check")
            .Table(table => table.Headers("Observation", "Next check", "Owner")
                .Row("All users affected", "Service health and dependencies", "Operations")
                .Row("One group affected", "Access and routing", "Support")
                .Row("Failure after a change", "Deployment evidence and rollback readiness", "Engineering"))
            .H2("3. Communicate")
            .Code("text", "Impact: <what users cannot do>\nOwner: <named coordinator>\nNext action: <specific check>\nNext update: <time>")
            .H2("4. Close with evidence")
            .P("Confirm recovery with an affected user, record the timeline, and assign follow-up actions.");
        File.WriteAllText(Path.Combine(folder, "example.md"), document.ToMarkdown());
    }
}

